import { Component, OnInit } from '@angular/core';
import {CouncillorClass} from '../councillor-class';
import {CouncillorService} from '../councillor.service';
import {TermServiceService} from '../term-service.service';
import {Term} from '../term';
import {TermClass} from '../TermClass';
import {ICouncillor} from '../ICouncillor';

@Component({
  selector: 'app-councillors',
  templateUrl: './councillors.component.html',
  styleUrls: ['./councillors.component.css']
})
export class CouncillorsComponent implements OnInit {

  councillorList: CouncillorClass[];
  activeTerm: Term = new TermClass();

  constructor(private councillorService: CouncillorService,
              private termService: TermServiceService) { }


  ngOnInit() {
    this.getAllCouncillors();

    this.termService.getActiveTerm()
    // @ts-ignore
      .subscribe(res => this.activeTerm = res.activeTerm);
  }

  getAllCouncillors() {
    this.councillorService.getCouncillors()
    // @ts-ignore
      .subscribe(res => this.councillorList = res.councillors);
  }

  deleteCouncillor(councillor: ICouncillor) {
    if (!confirm(`Usunąć radnego ${councillor.name} ${councillor.surname}?`)) { return; }
    this.councillorService.deleteCouncillor(councillor.uuid)
      .subscribe(res => this.getAllCouncillors());
  }

}
