import { Injectable } from '@angular/core';
import {HttpClient} from '@angular/common/http';
import {Config} from '../config';
import {Observable} from 'rxjs';

@Injectable({
  providedIn: 'root'
})
export class ConfigService {

  constructor(private httpClient: HttpClient) { }

  getAllConfigs() {
    return this.httpClient.get(Config.URI_AllConfig);
  }

  getConfig() {
    return this.httpClient.get(`${Config.URI_ALLConfigs}`);
  }

  setConfig(configKey, configValue) {
    return this.httpClient.put(`${Config.URI_AllConfig}`, {configKey: configKey, configValue: configValue});
  }
}
