import {Component, OnInit} from '@angular/core';
import {TermServiceService} from '../../term-service.service';
import {FormBuilder, FormGroup, Validators} from '@angular/forms';
import {ActivatedRoute, Router} from '@angular/router';
import {Term} from '../../term';
import {ICouncillor} from '../../ICouncillor';
import {CouncillorClass} from '../../councillor-class';
import {CouncillorService} from '../../councillor.service';
import {UtilitiesService} from '../../utilities.service';
import {SittingClass} from '../../sitting-class';
import {Location} from '@angular/common';

@Component({
  selector: 'app-councillor-form',
  templateUrl: './councillor-form.component.html',
  styleUrls: ['./councillor-form.component.css']
})
export class CouncillorFormComponent implements OnInit {

  termsList: Term[];
  constituenciesList: number[];
  usersList;
  councillor: ICouncillor;

  councillorForm: FormGroup = this.formBuilder.group({
    committee: ['', Validators.required],
    term_id: ['', Validators.required],
    constituency: ['', Validators.required],
    users_uuid: ['', Validators.required]
  });

  submitCouncillorForm() {
    this.councillor.users_uuid = this.councillorForm.value.users_uuid;
    this.councillor.committee = this.councillorForm.value.committee;
    this.councillor.terms_id = this.councillorForm.value.term_id;
    this.councillor.constituency = this.councillorForm.value.constituency;

    this.saveCouncillorForm();
  }

  private saveCouncillorForm() {
    if (this.councillor.hasOwnProperty('uuid')) {
      this.councillorService.editCouncillor(this.councillor)
        .subscribe((res) => {
            this.router.navigateByUrl('/councillors');
          },
          error1 => console.log(error1.error)
        );
    } else {
      this.councillorService.saveCouncillor(this.councillor)
        .subscribe((res) => {
            this.router.navigateByUrl('/councillors');
          },
          error1 => console.log(error1)
        );
    }
  }

  resetForm() {
    this.councillorForm.reset();
  }

  constructor(private termService: TermServiceService,
              private formBuilder: FormBuilder,
              private councillorService: CouncillorService,
              private utilitiesService: UtilitiesService,
              private router: Router,
              private location: Location,
              private activateRoute: ActivatedRoute) {
  }

  ngOnInit() {

    this.termService.getTerms()
    // @ts-ignore
      .subscribe(res => this.termsList = res.terms);

    this.utilitiesService.getConstituencies()
    // @ts-ignore
      .subscribe(res => this.constituenciesList = res.constituencies);

    if (this.activateRoute.snapshot.params.uuid === undefined) {
      this.councillor = new CouncillorClass();

      this.utilitiesService.getUsableUsers()
      // @ts-ignore
        .subscribe(res => this.usersList = res.users);
    } else {
      this.setDataFromResolver();
    }

  }

  private setDataFromResolver() {
    // wczytaj dane z resovera do formularza
    this.activateRoute.data
      .subscribe(res => {

          this.utilitiesService.getUsers()
            // @ts-ignore
            .subscribe(res => this.usersList = res.users);
          this.councillor = new CouncillorClass();
          // @ts-ignore
          Object.assign(this.councillor, res.data.councillor);
          this.councillorForm = this.formBuilder.group({
            uuid: [this.councillor.uuid],
            users_uuid: [this.councillor.users_uuid, Validators.required],
            committee: [this.councillor.committee, Validators.required],
            term_id: [this.councillor.terms_id, Validators.required],
            constituency: [this.councillor.constituency, Validators.required],
            created_at: [this.councillor.created_at],
            updated_at: [this.councillor.updated_at],
          });
        }
      );
  }

  goBack() {
    this.location.back();
  }
}
