import { Injectable } from '@angular/core';
import {SittingService} from '../../sitting.service';
import {ActivatedRouteSnapshot, Resolve, RouterStateSnapshot} from '@angular/router';
import {Observable} from 'rxjs';
import {ISitting} from '../../isitting';

@Injectable({
  providedIn: 'root'
})
export class SittingFormResolverService implements Resolve<any> {

  constructor(private sittingService: SittingService) { }

  resolve(route: ActivatedRouteSnapshot, state: RouterStateSnapshot): Observable<any> {
    const uuid = route.params.uuid;
    return this.sittingService.getSitting(uuid);
  }
}
