import {LoginComponent} from './login/login.component';
import {AuthGuard} from './guards/auth-guard.service';
import {HomeComponent} from './home/home.component';
import {TermsComponent} from './terms/terms.component';
import {TermFormComponent} from './terms/term-form/term-form.component';
import {AdminGuard} from './guards/admin.guard';
import {SittingsComponent} from './sittings/sittings.component';
import {SittingFormComponent} from './sittings/sitting-form/sitting-form.component';
import {SittingFormResolverService} from './sittings/sitting-form/sitting-form-resolver.service';
import {SittingPresenceListComponent} from './sitting-presence-list/sitting-presence-list.component';
import {VotingsComponent} from './votings/votings.component';
import {VotingFormComponent} from './votings/voting-form/voting-form.component';
import {VotingResolverService} from './votings/voting-resolver.service';
import {VotingResultComponent} from './voting-result/voting-result.component';
import {VotingResultResolverService} from './voting-result/voting-result-resolver.service';
import {CouncillorsComponent} from './councillors/councillors.component';
import {CouncillorFormComponent} from './councillors/councillor-form/councillor-form.component';
import {UserComponent} from './users/user.component';
import {ConfigComponent} from './configs/config.component';
import {UserFormComponent} from './users/user-form/user-form.component';
import {AppComponent} from './app.component';
import {Routes} from '@angular/router';
import {CouncillorsResolverService} from './councillors/councillors-resolver.service';
import {ConfigResolverService} from './configs/config-resolver.service';

export const routes: Routes = [
  {path: 'login', component: LoginComponent},
  {
    path: '', canActivate: [AuthGuard], canActivateChild: [AuthGuard], children: [

      {path: 'home', component: HomeComponent},

      {path: 'config', component: ConfigComponent, canActivate: [AdminGuard], resolve: {data: ConfigResolverService}},

      {path: 'terms', component: TermsComponent},
      {path: 'terms/create-form', component: TermFormComponent, canActivate: [AdminGuard]},
      {path: 'terms/edit-form/:id', component: TermFormComponent, canActivate: [AdminGuard]},

      {path: 'sittings', component: SittingsComponent},
      {path: 'sittings/create-form', component: SittingFormComponent, canActivate: [AdminGuard]},
      {
        path: 'sittings/edit-form/:uuid',
        resolve: {data: SittingFormResolverService}, component: SittingFormComponent, canActivate: [AdminGuard]
      },
      {path: 'sittings/presence-list/:sitting_uuid', component: SittingPresenceListComponent, canActivate: [AdminGuard]},

      {path: 'votings', component: VotingsComponent},
      {path: 'votings/create-form', component: VotingFormComponent, canActivate: [AdminGuard]},
      {
        path: 'votings/edit-form/:uuid',
        resolve: {data: VotingResolverService}, component: VotingFormComponent, canActivate: [AdminGuard]
      },
      {
        path: 'votings/result/:uuid', component: VotingResultComponent,
        resolve: {data: VotingResultResolverService}, canActivate: [AdminGuard]
      },

      {path: 'councillors', component: CouncillorsComponent, canActivate: [AdminGuard]},
      {path: 'councillors/create-form', component: CouncillorFormComponent, canActivate: [AdminGuard]},
      {
        path: 'councillors/edit-form/:uuid', component: CouncillorFormComponent,
        resolve: {data: CouncillorsResolverService}, canActivate: [AdminGuard]
      },

      {path: 'users', component: UserComponent, canActivate: [AdminGuard]},
      {path: 'users/create-form', component: UserFormComponent, canActivate: [AdminGuard]},
      {path: 'users/edit-form/:uuid', component: UserFormComponent, canActivate: [AdminGuard]},
      {path: '**', component: HomeComponent},
    ]
  },

  {path: '**', component: AppComponent, canActivate: [AuthGuard]}
];
