import { Injectable } from '@angular/core';
import {ActivatedRouteSnapshot, Resolve, RouterStateSnapshot} from '@angular/router';
import {Observable} from 'rxjs';
import {CouncillorService} from '../councillor.service';

@Injectable({
  providedIn: 'root'
})
export class CouncillorsResolverService implements Resolve<any> {

  constructor(private councillorService: CouncillorService) { }

  resolve(route: ActivatedRouteSnapshot, state: RouterStateSnapshot): Observable<any> {
    const uuid = route.params.uuid;
    return this.councillorService.getCouncillor(uuid);
  }
}
