import {Injectable} from '@angular/core';
import {HttpErrorResponse, HttpEvent, HttpHandler, HttpInterceptor, HttpRequest, HttpResponse,} from '@angular/common/http';

import {Observable} from 'rxjs';
import {tap} from 'rxjs/operators';
import {AlertService} from './alert.service';
import {LoginService} from './login.service';
import {AlertType} from './alert-type.enum';

@Injectable()
export class RequestInterceptor implements HttpInterceptor {

  constructor(private alertService: AlertService,
              private loginService: LoginService) {}

  intercept(request: HttpRequest<any>, next: HttpHandler): Observable<HttpEvent<any>> {

    return next.handle(request)
      .pipe(
        tap(
          evt => {
            if (evt instanceof HttpResponse) {
              const timeToLogout = evt.headers.get('timeToLogout');
              this.loginService.timeToLogout.next(timeToLogout);
            }
          }
        ),
        tap((event: HttpEvent<any>) => {
        }, (err) => {
          if (err instanceof HttpErrorResponse) {
            switch (err.status) {
              case 401:
                this.loginService.clearLocalStorageLogin(); break;
              case 422:
                this.alertService.emitAlertNext({type: AlertType.error, title: 'Ta operacja już została wykonana',
                  message: 'Nie można jej powtórzyć!'}); break;
              case 503:
                this.alertService.emitAlertNext({type: AlertType.error, title: 'Błąd serwisu 503',
                  message: 'Błąd połaczenia z serwisem lub bazą danych'}); break;
            }
          }
        }),
        );
    }
}
