import { Component, OnInit } from '@angular/core';
import {TermServiceService} from '../term-service.service'
import {Observable} from "rxjs";
import {Term} from "../term";

@Component({
  selector: 'app-terms',
  templateUrl: './terms.component.html',
  styleUrls: ['./terms.component.css']
})
export class TermsComponent implements OnInit {
  terms: Term[];

  deleteTerm(t: Term) {
    if (!confirm(`Usunąć kadencję ${t.start_date} - ${t.end_date}`)) return;
    this.termsService.deleteTerm(t.id)
      .subscribe(res=> {
        this.getAllTerms();
      // @ts-ignore
        jQuery('#infoModal').modal();
      })
  }

  getAllTerms() {
    this.termsService.getTerms()
      .subscribe((res)=> {
        // @ts-ignore
          this.terms = res.terms;
        },
        error1 => console.log(error1)
      )
  }

  constructor(private termsService: TermServiceService) { }

  ngOnInit() {
    this.getAllTerms();
  }

}
