import { Injectable } from '@angular/core';
import {Observable} from "rxjs";
import {IVoting} from "./ivoting";
import {Config} from "./config";
import {HttpClient} from "@angular/common/http";

@Injectable({
  providedIn: 'root'
})
export class VotingTypeService {

  getVotingType(id): Observable<any> {
    return this.$http.get<any>(`${Config.URI_AllVotingTypes}/${id}`);
  }

  getVotingTypes() {
    return this.$http.get<any[]>(Config.URI_AllVotingTypes);
  }

  constructor(private $http: HttpClient) { }
}
