import {Component, OnInit} from '@angular/core';
import {Location} from '@angular/common';
import {FormBuilder, FormGroup, Validators} from '@angular/forms';
import {CouncillorService} from '../../councillor.service';
import {UtilitiesService} from '../../utilities.service';
import {ActivatedRoute, Router} from '@angular/router';
import {CouncillorClass} from '../../councillor-class';
import {UserClass} from '../../user-class';
import {IUser} from '../../iuser';
import {UserService} from '../../user.service';

@Component({
  selector: 'app-user-form',
  templateUrl: './user-form.component.html',
  styleUrls: ['./user-form.component.css']
})
export class UserFormComponent implements OnInit {

  user: IUser;

  userForm: FormGroup = this.formBuilder.group({
    name: ['', Validators.required],
    surname: ['', Validators.required],
    email: ['', Validators.email],
    password: ['', Validators.required],
    role: ['', Validators.required],
    can_vote: false
  });

  constructor(private formBuilder: FormBuilder,
              private utilitiesService: UtilitiesService,
              private userService: UserService,
              private router: Router,
              private location: Location,
              private activateRoute: ActivatedRoute) {
  }

  ngOnInit() {
    // tslint:disable-next-line:max-line-length
    this.activateRoute.snapshot.params.uuid === undefined ? this.user = new UserClass() : this.userService.getUser(this.activateRoute.snapshot.params.uuid)
      .subscribe(res => {
          this.user = new UserClass();
          // @ts-ignore
        Object.assign(this.user, res.user);
          this.userForm = this.formBuilder.group({
            uuid: [this.user.uuid],
            name: [this.user.name, Validators.required],
            surname: [this.user.surname, Validators.required],
            email: [this.user.email, Validators.email],
            password: ['', Validators.required],
            role: [this.user.role, Validators.required],
            can_vote: [this.user.can_vote],
            created_at: [this.user.created_at],
            updated_at: [this.user.updated_at],
          });

        }
      );
  }

  submitUserForm() {
    this.user.name = this.userForm.value.name;
    this.user.surname = this.userForm.value.surname;
    this.user.email = this.userForm.value.email;
    this.user.password = this.userForm.value.password;
    this.user.role = this.userForm.value.role;
    this.user.can_vote = this.userForm.value.can_vote;

    this.saveUserForm();
  }

  resetForm() {
    this.userForm.reset();
  }

  private saveUserForm() {
    if (this.user.hasOwnProperty('uuid')) {
      this.userService.editUser(this.user)
        .subscribe((res) => {
            this.router.navigateByUrl('/users');
          },
          error1 => console.log(error1.error)
        );
    } else {
      this.userService.saveUser(this.user)
        .subscribe((res) => {
            this.router.navigateByUrl('/users');
          },
          error1 => alert(`Błąd zapisu: ${error1.message}`)
        );
    }
  }

  goBack() {
    this.location.back();
  }

}
