import {AfterViewInit, Component, OnInit} from '@angular/core';
import {AlertService} from './alert.service';
import {ActivatedRoute, Router} from '@angular/router';
import {UtilitiesService} from './utilities.service';
import {LoginService} from './login.service';
import {UserClass} from './user-class';
import {ToastrService} from 'ngx-toastr';
import {IAlert} from './ialert';
import {AlertType} from './alert-type.enum';
import {ConfigService} from './configs/config.service';
import {filter, isEmpty, mergeMap} from 'rxjs/operators';
import {BehaviorSubject, EMPTY} from 'rxjs';
import {Config} from './config';

@Component({
  selector: 'app-root',
  templateUrl: './app.component.html',
  styleUrls: ['./app.component.css']
})
export class AppComponent implements OnInit {
  title = 'eRada';
  user = new UserClass();

  configJednostka = '';
  configNavbarTheme  = '';
  configNavbarColor = '';
  private socket;

  constructor(private alertService: AlertService,
              private activatedRoute: ActivatedRoute,
              private router: Router,
              private configService: ConfigService,
              private utilitiesService: UtilitiesService,
              private loginService: LoginService,
              private toastr: ToastrService) {

    this.socket = this.utilitiesService.socket;

    this.alertService.emitAlertEvent$
      .subscribe(data => {
        this.showAlertEvent(data);
      });
  }

  ngOnInit(): void {
    this.loginService.loggedUser
      .pipe(mergeMap(v => {
        if (v.uuid) {
          Object.assign(this.user, JSON.parse(localStorage.getItem('user')));
          // return this.configService.getConfig('jednostka');
          return this.configService.getConfig();
        } else {
          // @ts-ignore
          this.user = {};
          return EMPTY;
        }
      }),
      filter( v => v !== null && Object.values(v).length > 0))
      .subscribe(res => {
        this.setConfigData(res);
      });
  }

  setConfigData(config) {
    this.configJednostka = config.find(c => c.key === Config.ConfigNameJednostka).value;
    this.configNavbarTheme = config.find(c => c.key === Config.ConfigNameNavbarTheme).value;
    this.configNavbarColor = config.find(c => c.key === Config.ConfigNameNavbarColor).value;
  }

  showAlertEvent(data: IAlert) {
    const {type, message, title} = data;

    switch (type) {
      case AlertType.error:
        this.toastr.error(message, title);
        break;
      case AlertType.info:
        this.toastr.info(message, title);
        break;
      case AlertType.success:
        this.toastr.success(message, title);
        break;
      case AlertType.warning:
        this.toastr.warning(message, title);
        break;
    }
  }


}
