import { Injectable } from '@angular/core';
import {Observable} from 'rxjs';
import {Config} from './config';
import {HttpClient} from '@angular/common/http';
import {IVoting} from './ivoting';
import { retry } from 'rxjs/operators';

@Injectable({
  providedIn: 'root'
})
export class VotingService {

  constructor(private $http: HttpClient) { }

  getLastVotingNumber(sitting_id) {
    return this.$http.get(`${Config.URI_VotingLastNumber}/${sitting_id}`);
  }

  getVoting(uuid: string): Observable<IVoting> {
    return this.$http.get<IVoting>(`${Config.URI_AllVotings}/${uuid}`);
  }

  setActiveVoting(uuid): Observable<any> {
    return this.$http.put(Config.URI_SetActiveVoting, {uuid});
  }

  setNotActiveVoting(uuid): Observable<any> {
    return this.$http.put(Config.URI_SetNotActiveVoting, {uuid});
  }

  vote(result, uuid) {
    return this.$http.post(Config.URI_Vote, {result: result, uuid: uuid})
      .pipe(
      retry(3)
    );
  }

  getActiveVoting() {
    return this.$http.get<IVoting>(Config.URI_ActiveVoting);
  }

  getVotings() {
    return this.$http.get<IVoting[]>(Config.URI_AllVotings);
  }

  saveVoting(voting: IVoting): Observable<number> {
    return this.$http.post<number>(Config.URI_SaveVoting, voting);
  }

  editVoting(voting: IVoting): Observable<number> {
    return this.$http.put<number>(Config.URI_SaveVoting, voting);
  }

  deleteVoting(id) {
    const address = `${Config.URI_DeleteVoting}/${id}`;
    return this.$http.delete(address);
  }
}
