import { Component, OnInit } from '@angular/core';
import {SittingService} from '../sitting.service';
import {ActivatedRoute} from '@angular/router';
import {ISitting} from '../isitting';
import {SittingClass} from '../sitting-class';
import {UtilitiesService} from '../utilities.service';
import {Location} from '@angular/common';
import {IUser} from '../iuser';
import {LoginService} from '../login.service';
import {UserClass} from '../user-class';

@Component({
  selector: 'app-sitting-presence-list',
  templateUrl: './sitting-presence-list.component.html',
  styleUrls: ['./sitting-presence-list.component.css']
})
export class SittingPresenceListComponent implements OnInit {

  socket;
  sitting_uuid: String;
  sittingPresenceList = [];
  user: IUser = new UserClass();
  sitting: ISitting = new SittingClass();

  constructor(private sittingService: SittingService,
              private loginService: LoginService,
              private activateRoute: ActivatedRoute,
              private location: Location,
              private utilitiesService: UtilitiesService) {

    this.sitting_uuid = this.activateRoute.snapshot.params.sitting_uuid;
    this.socket = this.utilitiesService.socket;
    this.socket.on('sittings-presence', v => {
      this.getSittingPresenceList(this.sitting_uuid);
    });
  }

  ngOnInit() {
    this.getSittingPresenceList(this.sitting_uuid);
    this.loginService.loggedUser
      .subscribe(v => Object.assign(this.user, JSON.parse(localStorage.getItem('user'))));
  }

  private getSittingPresenceList(sitting_uuid) {
    this.sittingService.getSittingPresenceList(sitting_uuid)
      .subscribe(res => {
        // @ts-ignore
        this.sitting = res.sitting[0];
        // @ts-ignore
        this.sittingPresenceList = res.sitting_presence_list;
      });
  }

  deletePresence(uuid) {
    if (!confirm(`Usunąć obecność?`)) return;
    this.sittingService.deletePresence(uuid)
      .subscribe(res => {
        this.getSittingPresenceList(this.sitting_uuid);
      });
  }

  goBack() {
    this.location.back();
  }
}
