import {Component, Injectable, OnInit} from '@angular/core';
import {FormBuilder, FormGroup, Validators} from '@angular/forms';
import {Term} from "../../term";
import {TermServiceService} from '../../term-service.service'
import {TermClass} from "../../TermClass";
import {ActivatedRoute, Router} from "@angular/router";
import {filter, find, map} from "rxjs/operators";
import {fromPromise} from "rxjs/internal-compatibility";
import {someAncestor} from "tslint";
import {hasProperties} from "codelyzer/util/astQuery";
import {AlertService} from "../../alert.service";


@Component({
  selector: 'app-term-form',
  templateUrl: './term-form.component.html',
  styleUrls: ['./term-form.component.css']
})
export class TermFormComponent implements OnInit {

  term: Term;
  termForm: FormGroup = this.formBuilder.group({
    start_date: ['', Validators.required],
    end_date: ['', Validators.required],
    active: true
  });


  submitTermForm() {
    this.term.start_date = this.termForm.value.start_date;
    this.term.end_date = this.termForm.value.end_date;
    this.term.active = this.termForm.value.active;

    if (this.term.active) {
      let isAnyActive = this.termService.getTerms()
        .pipe(
          // @ts-ignore
          map(res => res.terms)
        )
        .subscribe(terms => {
          if (terms.some(e => e.active)) {
            if (!confirm('Zostało zaznaczone pole Czy aktualna?. Zastapić aktualną kadencję na nową?')) {
              this.term.active = false;
            }
          }
          this.saveTermForm();
        })

    } else {
      this.saveTermForm();

    }
  }

  saveTermForm() {
    if (this.term.hasOwnProperty('id')) {
      this.termService.editTerm(this.term)
        .subscribe((res) => {
            this.router.navigateByUrl('/terms');

          },
          error1 => console.log(error1.error)
        )
    } else {
      this.termService.saveTerm(this.term)
        .subscribe((res) => {
            this.router.navigateByUrl('/terms');
          },
          error1 => console.log(error1)
        )
    }


  }

  resetForm() {
    this.termForm.reset();
  }

  constructor(private formBuilder: FormBuilder,
              private termService: TermServiceService,
              private router: Router,
              private activateRoute: ActivatedRoute,
              private alertService: AlertService) {
  }

  ngOnInit() {
    isNaN(this.activateRoute.snapshot.params.id) ? this.term = new TermClass() : this.termService.getTerm(this.activateRoute.snapshot.params.id)
      .subscribe(res => {
        // @ts-ignore
        this.term = res.term;
        this.termForm = this.formBuilder.group({
          start_date: [this.term.start_date.substring(0, 10), Validators.required],
          end_date: [this.term.end_date.substring(0, 10), Validators.required],
          active: this.term.active
        });

      }
    );


  }


}
