/* tslint:disable:quotemark */
import { Injectable } from '@angular/core';
import {Observable} from 'rxjs';
import {Config} from './config';
import {HttpClient} from "@angular/common/http";
import {ICouncillor} from "./ICouncillor";

@Injectable({
  providedIn: 'root'
})
export class CouncillorService {

  constructor(private $http: HttpClient) { }

  saveCouncillor(councillor: ICouncillor): Observable<number> {
    return this.$http.post<number>(Config.URI_SaveCouncillor, councillor);
  }

  getCouncillors() {
    return this.$http.get(Config.URI_AllCouncillors);
  }

  getCouncillor(uuid) {
    return this.$http.get(`${Config.URI_AllCouncillors}/${uuid}`);
  }

  editCouncillor(ICouncillor: ICouncillor): Observable<number> {
    return this.$http.put<number>(Config.URI_SaveCouncillor, ICouncillor);
  }

  deleteCouncillor(uuid) {
    return this.$http.delete(`${Config.URI_AllCouncillors}/${uuid}`);
  }
}
