import {Component, OnInit} from '@angular/core';
import {ISitting} from '../../isitting';
import {FormBuilder, FormGroup, Validators} from '@angular/forms';
import {TermServiceService} from '../../term-service.service';
import {SittingService} from '../../sitting.service';
import {ActivatedRoute, Router} from '@angular/router';
import {IVoting} from '../../ivoting';
import {VotingService} from '../../voting.service';
import {VotingClass} from '../../voting-class';
import {VotingTypeService} from '../../voting-type.service';
import {AlertService} from '../../alert.service';
import {Location} from '@angular/common';
import {AlertType} from '../../alert-type.enum';

@Component({
  selector: 'app-voting-form',
  templateUrl: './voting-form.component.html',
  styleUrls: ['./voting-form.component.css']
})
export class VotingFormComponent implements OnInit {

  sittingsList: ISitting[];
  votingTypesList;
  voting: IVoting;
  stayAfterSave = false;

  votingForm: FormGroup = this.formBuilder.group({
    queue: ['', [Validators.required, Validators.pattern('[0-9]+')]],
    name: ['', Validators.required],
    sitting_id: ['', Validators.required],
    vote_type_id: ['', Validators.required],
    active: false
  });

  constructor(private termService: TermServiceService,
              private formBuilder: FormBuilder,
              private sittingService: SittingService,
              private votingService: VotingService,
              private votingTypesService: VotingTypeService,
              private router: Router,
              private location: Location,
              private activateRoute: ActivatedRoute,
              private alertService: AlertService) {
  }

  ngOnInit() {
    // @ts-ignore
    this.sittingService.getSittings()// @ts-ignore
    // @ts-ignore
      .subscribe(res => {
        // @ts-ignore
        this.sittingsList = res.sittings;
        //if (!this.voting.hasOwnProperty('id')) { this.votingForm.value.sitting_id = this.sittingsList.find(s=> s.active==1).uuid; }

      });

    this.votingTypesService.getVotingTypes()
    // @ts-ignore
      .subscribe(res => this.votingTypesList = res.votingTypes);

    this.activateRoute.snapshot.params.uuid === undefined ? this.voting = new VotingClass() : this.setDataFromResolver();
  }

  submitVotingForm() {
    this.voting.queue = this.votingForm.value.queue;
    this.voting.name = this.votingForm.value.name;
    this.voting.sitting_id = this.votingForm.value.sitting_id;
    this.voting.vote_type_id = this.votingForm.value.vote_type_id;
    this.voting.active = this.votingForm.value.active;

    this.saveVotingForm();
  }

  setDataFromResolver() {
    this.activateRoute.data
      .subscribe(res => {
        this.voting = new VotingClass();
        // @ts-ignore
        Object.assign(this.voting, res.data.voting);
        this.votingForm = this.formBuilder.group({
          uuid: [this.voting.uuid],
          vote_type_id: [this.voting.vote_type_id, Validators.required],
          name: [this.voting.name, Validators.required],
          queue: [this.voting.queue, [Validators.required, Validators.pattern('[0-9]*')]],
          sitting_id: [this.voting.sitting_id, Validators.required],
          active: this.voting.active,
          created_at: [this.voting.created_at],
          updated_at: [this.voting.updated_at],
        });
      });
  }

  resetForm() {
    this.votingForm.reset();
    this.votingForm.controls.active.patchValue(false);
    console.log(this.votingForm.value.active);
  }

  onSittingChange(sitting_id) {
    // @ts-ignore
    this.votingService.getLastVotingNumber(sitting_id)
      .toPromise()
      // @ts-ignore
      .then(res => this.votingForm.patchValue({queue: res.last_queue + 1}))
      .catch(err => alert(err));
  }

  saveAndStay() {
    this.stayAfterSave = true;
    this.submitVotingForm();
  }

  saveVotingForm() {
    if (this.voting.hasOwnProperty('id')) {
      this.votingService.editVoting(this.voting)
        .subscribe((res) => {
            this.router.navigateByUrl('/votings');
            this.alertService.emitAlertNext({type: AlertType.success, title: 'Zakończono edycję',
              message: `Głosowanie zostało edytowane`});
          },
          error1 => console.log(error1.error)
        );
    } else {
      this.votingService.saveVoting(this.voting)
        .subscribe((res) => {
            if (this.stayAfterSave) {
              this.resetForm();
            } else {
              this.router.navigateByUrl('/votings');
            }
            this.alertService.emitAlertNext({type: AlertType.success, title: 'Zapisano glosowanie',
              message: `Nowe głosowanie zostało dodane.`});
          },
          error1 => console.log(error1)
        );
    }
  }

  goBack() {
    this.location.back();
  }

}
