import {Component, OnInit, AfterViewInit} from '@angular/core';
import {VotingResultService} from '../voting-result.service';
import {ActivatedRoute} from '@angular/router';
import {ISitting} from '../isitting';
import {UtilitiesService} from '../utilities.service';
import { Location } from '@angular/common';
import {} from 'angular2-chartjs';
import {AlertType} from '../alert-type.enum';
import {VotingService} from '../voting.service';

@Component({
  selector: 'app-voting-result',
  templateUrl: './voting-result.component.html',
  styleUrls: ['./voting-result.component.css']
})
export class VotingResultComponent implements OnInit, AfterViewInit {

  yes = 'za';
  no = 'przeciw';
  hold = 'wstrzymuję się';

  socket;
  sitting: ISitting;
  isVotingActive: boolean;
  countYes: number;
  countNO: number;
  countHold: number;
  votingResults: any;
  presentAndNoVotedArray: object[];
  votingUuid: string;

  resultArray: number[];
  private type;
  private data;
  private options;
  private present: any;


  constructor(private votingResultService: VotingResultService,
              private votingService: VotingService,
              private activatedRoute: ActivatedRoute,
              private location: Location,
              private utilitiesService: UtilitiesService) {

    this.socket = this.utilitiesService.socket;
    this.socket.on('vote', v => {
      if (v.uuid === this.votingResults.uuid) {
        this.getVotingResult();
      }
    });
  }

  ngOnInit() {
    this.activatedRoute.data
      .subscribe(res => this.setData(res.data));
  }

  deleteVote(vr_id, surname) {
    if (!confirm(`Czy na pewno chcesz usunąć głos radnego ${surname}?`)) { return; }
    this.votingResultService.deleteVote(vr_id)
      .subscribe(res => {
        // @ts-ignore
        if (res.affectedRows === 1) { this.getVotingResult(); }

      });

  }

  setActiveVoting() {
    this.votingService.setActiveVoting(this.votingUuid)
      .subscribe(res => {
        this.getVotingResult();
      });
  }

  getVotingResult() {
    this.votingResultService.getVotingResults(this.votingUuid)
      .subscribe(res => {
        this.setData(res);
      });
  }

  private setData(res) {
    this.votingUuid = this.activatedRoute.snapshot.params.uuid;
    this.votingResults = res.result;
    this.isVotingActive = res.active;
    this.sitting = res.sitting;
    this.present = res.present;

    const votingsArray = this.votingResults.map( p => p.councillors_id);
    const  presentsArray = this.present.map( p => p.councillors_id);

    const presentAndNoVotedSet = new Set(presentsArray.filter(p => !(new Set(votingsArray).has(p))));

    const presentAndNoVotedArray =  Array.from(presentAndNoVotedSet).map(i => {
      const councillor = [...this.present].find(p => p.councillors_id === i);
      return {
        councillors_id: i,
        name: councillor.name,
        surname: councillor.surname
      };
    });

    this.presentAndNoVotedArray = presentAndNoVotedArray;

    this.countYes = this.votingResults.filter(v => v.result === this.yes).length;
    this.countNO = this.votingResults.filter(v => v.result === this.no).length;
    this.countHold = this.votingResults.filter(v => v.result === this.hold).length;

    this.resultArray = [this.countYes, this.countNO, this.countHold];
    this.refreshChart();
  }

  goBack() {
    this.location.back();
  }

  ngAfterViewInit(): void {
    this.refreshChart();
  }

  private refreshChart() {
    this.type = 'bar';
    this.data = {
      labels: ['Za', 'Przeciw', 'Wstrzymany'],

      datasets: [
        {
          label: 'Wyniki głosowania',
          data: this.resultArray,
          backgroundColor: [
            'rgba(54, 162, 235, 0.2)',
            'rgba(255, 99, 132, 0.2)',
            'rgba(255, 206, 86, 0.2)'
          ]
        }
      ]
    };
    this.options = {
      legend: false,
      responsive: true,
      maintainAspectRatio: false,
      scales: {
        yAxes: [{
          ticks: {
            beginAtZero: true,
            callback: function (value) {
              if (value % 1 === 0) {
                return value;
              }
            }
          }
        }]
      }
    };
  }
}
