import { Injectable } from '@angular/core';
import {HttpClient} from '@angular/common/http';
import {BehaviorSubject, from, of} from 'rxjs';
import {Config} from './config';
import {Router} from '@angular/router';
import {IUser} from './iuser';
import {UserClass} from './user-class';
import {UtilitiesService} from './utilities.service';
import {AlertType} from './alert-type.enum';
import {AlertService} from './alert.service';
import {tap} from 'rxjs/operators';

@Injectable({
  providedIn: 'root'
})
export class LoginService {
  private _tempLogin = new UserClass();
  public sessionExpires;
  public loggedUser = new BehaviorSubject<IUser>(this._tempLogin);
  public timeToLogout = new BehaviorSubject<string>('');

  constructor(private $http: HttpClient,
              private router: Router,
              private alertService: AlertService,
              private utilitiesService: UtilitiesService) {
    if (!localStorage.getItem('user') || !JSON.parse(localStorage.getItem('user')).uuid) {
    } else {
      this.loggedUser.next(JSON.parse(localStorage.getItem('user')));
    }
  }

  tryLogin(email, password): any {
    return this.$http.post(Config.URI_Login, {email: email, password: password}, {withCredentials: true})
      .pipe(tap(
        res => {
          // @ts-ignore
          localStorage.setItem('user',  JSON.stringify(res.user));
          // @ts-ignore
          this.loggedUser.next(res.user);
          this.utilitiesService.connectToSocket();
          this.router.navigateByUrl('/home');
          this.alertService.emitAlertNext({type: AlertType.success, title: 'Witaj!',
            message: `Zalogowano poprawnie :)`});
        }
      ));
      /*.subscribe(,
      error1 => {
        error1.status === 400 ? alert('Niepoprawny email lub hasło') : alert(error1.message);
      });*/
  }

  public logout() {
    this.deleteSession();
    this.clearLocalStorageLogin();
  }

  public clearLocalStorageLogin() {
    // @ts-ignore
    this.loggedUser.next({});
    if (localStorage.getItem('user')) { localStorage.removeItem('user'); }
    this.router.navigateByUrl('/login');
  }

  public checkIfLogged(): boolean {
    if (localStorage.getItem('user') && localStorage.getItem('user').length > 0) {
      return true;
    } else {
      this.logout();
      return false;
    }

  }

  public deleteSession() {
    this.$http.delete('/api/logout')
      // .pipe(
      //   finalize( () => {
      //     console.log("fin");
      //
      //     this.utilitiesService.disconenctSocket();
      //       this.router.navigateByUrl('/login');
      //     }
      //   )
      // )
      .subscribe(res => {
          this.utilitiesService.disconenctSocket();
          this.router.navigateByUrl('/login');
        },
        error1 => {
        }
      );
  }
}
