import { Injectable } from '@angular/core';
import {ActivatedRouteSnapshot, Resolve, RouterStateSnapshot} from '@angular/router';
import {Observable} from 'rxjs';
import {VotingResultService} from '../voting-result.service';
@Injectable({
  providedIn: 'root'
})
export class VotingResultResolverService implements Resolve<any> {

  constructor(private votingResultService: VotingResultService) { }

  resolve(route: ActivatedRouteSnapshot,
          state: RouterStateSnapshot,
          ): Observable<any> | Promise<any> | any {
    const uuid = route.params.uuid;
    return this.votingResultService.getVotingResults(uuid);
  }
}
