import {Component, OnChanges, OnInit, SimpleChanges} from '@angular/core';
import {Input} from '@angular/core';
import {TermServiceService} from '../term-service.service';
import {Term} from '../term';
import {TermClass} from '../TermClass';
import {HttpClient} from '@angular/common/http';
import {LoginService} from '../login.service';
import {SittingService} from '../sitting.service';
import {ISitting} from '../isitting';
import {SittingClass} from '../sitting-class';
import {BehaviorSubject} from 'rxjs';


@Component({
  selector: 'app-navbar',
  templateUrl: './navbar.component.html',
  styleUrls: ['./navbar.component.css']
})
export class NavbarComponent implements OnInit, OnChanges {

  activeTerm: Term = new TermClass();
  activeSitting: ISitting = new SittingClass();
  timeToLogout: string;

  @Input() userType: string;
  @Input() AppName: string;
  @Input() jednostka: string;
  @Input() navbarTheme: string;
  @Input() navbarColor: string;
  @Input() UserName: string;
  @Input() UserSurname: string;

  constructor(private termService: TermServiceService,
              private sittingService: SittingService,
              private loginService: LoginService) {
  }

  ngOnInit() {
    this.sittingService.activeSitting
      .subscribe(res => {
        // @ts-ignore
        this.activeSitting = res;
      });
    this.loginService.timeToLogout
      .subscribe(val => {
        this.timeToLogout = val;
      });

  }

  ngOnChanges(changes: SimpleChanges): void {
    if (changes.userType !== undefined && changes.userType.currentValue !== undefined) {
      this.termService.getActiveTerm()
        .subscribe(res => {
          // @ts-ignore
          Object.keys(res).length === 1 ? this.activeTerm = res.activeTerm : {start_date: '-', end_date: '-'};
        });

/*      this.sittingService.activeSitting
        .subscribe(res => {
          console.log("navbar");
          console.log(res);
          // @ts-ignore
          console.log(Object.keys(res).length);
          // @ts-ignore
          Object.keys(res).length > 0 ? this.activeSitting = res : {number: '0', date: '0000-00-00'};
        });*/

    }

  }


  logout() {
    this.loginService.logout();
  }

}
