import { Component, OnInit } from '@angular/core';
import {ISitting} from '../isitting';
import {IVoting} from '../ivoting';
import {VotingService} from '../voting.service';
import {SittingClass} from '../sitting-class';
import {SittingService} from '../sitting.service';
import {UtilitiesService} from '../utilities.service';
import {AlertService} from '../alert.service';
import {AlertType} from '../alert-type.enum';
import {jsPDF} from 'jspdf';
import html2canvas from 'html2canvas';
import {HttpClient} from '@angular/common/http';
import {Config} from '../config';
import {concatMap, switchMap} from 'rxjs/operators';

@Component({
  selector: 'app-votings',
  templateUrl: './votings.component.html',
  styleUrls: ['./votings.component.css']
})
export class VotingsComponent implements OnInit {

  votings: IVoting[];
  activeSitting: ISitting = new SittingClass();
  user = JSON.parse(localStorage.getItem('user'));
  voting: IVoting;
  private socket;
  users_vote;
  docToPrint = new jsPDF('p', 'mm', 'a4'); // A4 size page of PDF

  constructor(private votingService: VotingService,
              private sittingService: SittingService,
              private utilitiesService: UtilitiesService,
              private alertService: AlertService,
              private httpClient: HttpClient) {

    this.socket = this.utilitiesService.socket;
    this.socket.on('vote', d => {
      const voting_index_where_vote = this.votings.findIndex(v => v.uuid === d.voting_uuid);
      if (voting_index_where_vote !== -1) {
        this.votings[voting_index_where_vote].votes++;
      }
    });
    this.socket.on('new-voting-active', d => this.getAllVotings());
  }

  ngOnInit() {
    this.getAllVotings();

    this.sittingService.getActiveSitting()
    // @ts-ignore
      .subscribe(res => this.activeSitting = res.activeSitting);
  }

  printVoting(votingId: string) {
      const votingResultUrl = `${Config.URI_VotingResult}/${votingId}`;
      this.httpClient.get(votingResultUrl)
        .pipe(
          concatMap((res) => {
            return this.httpClient.post(`${Config.URI_PrintVotingResult}/${votingId}`, res, {responseType: 'text'});
          })
        )
        .subscribe( res => {
          const divToPrint = document.createTextNode(res);
          html2canvas(divToPrint).then(canvas => {
            const imgWidth = 208;
            const pageHeight = 295;
            const imgHeight = canvas.height * imgWidth / canvas.width;
            const heightLeft = imgHeight;

            const contentDataURL = canvas.toDataURL('image/png');

            const position = 0;
            this.docToPrint.addImage(contentDataURL, 'PNG', 0, position, imgWidth, imgHeight);
            this.docToPrint.save(`glosowanie-${votingId}.pdf`);
          });

          });
  }

  deleteVoting(v: IVoting) {
    if (!confirm(`Usunąć głosowanie ${v.name}?`)) return;
    this.votingService.deleteVoting(v.uuid)
      .subscribe(res => {
        this.getAllVotings();
        this.alertService.emitAlertNext({type: AlertType.info, title: 'Usunięto!',
          message: 'Głosowanie zostało usunięte'});
      });
  }

  setActiveVoting(uuid) {
    this.votingService.setActiveVoting(uuid)
      .subscribe(res => {
        this.getAllVotings();
        this.alertService.emitAlertNext({type: AlertType.success, title: 'Głosowanie aktywne',
          message: 'Nowe głosowanie zostało aktywowane'});
      });
  }

  setNotActiveVoting(uuid) {
    this.votingService.setNotActiveVoting(uuid)
      .subscribe(res => {
        this.getAllVotings();
        this.alertService.emitAlertNext({type: AlertType.success, title: 'Głosowanie nieaktywne',
          message: 'Głosowanie zostało dezaktywowane'});
      });
  }

  hideVotings(): boolean {
    return (this.votings === undefined || this.votings.length === 0 || this.votings[0].updated_at == null);
  }

  vote(result, uuid) {
    this.votingService.vote(result, uuid)
      .subscribe(res => {
        // @ts-ignore
          if (res.status === 'ok') {
            if (this.users_vote) { return; }
            this.users_vote = {result: result, uuid: uuid};
            this.alertService.emitAlertNext({type: AlertType.success, title: 'Oddano głos',
              message: `Zagłosowałeś ${result}`});
        }
          // @ts-ignore
          if (res.errno === 1062) {
            this.alertService.emitAlertNext({type: AlertType.error, title: 'Błąd',
              message: `Już oddałeś głos`});
          }
      },
        error1 => {
          //if (true) {
            this.alertService.emitAlertNext({type: AlertType.error, title: 'Nieznany błąd',
              message: `Wystąpił błąd. Spróbuj odświerzyć stronę.`});
          //}
        }
      );
  }


  getAllVotings() {
    this.votingService.getVotings()
      .subscribe((res) => {
          // @ts-ignore
          this.votings = res.votings;
          // @ts-ignore
          if (res.v !== undefined) {
            // @ts-ignore
            this.users_vote = res.v[0];
          }
        },
        error1 => alert(error1)
      );
  }

}
