import { Injectable } from '@angular/core';
import {BehaviorSubject, Observable, of} from 'rxjs';
import {Config} from './config';
import {HttpClient} from '@angular/common/http';
import {ISitting} from './isitting';
import {catchError, map} from 'rxjs/operators';
import {error} from 'util';
import {SittingClass} from './sitting-class';

@Injectable({
  providedIn: 'root'
})
export class SittingService {

  private _tempActiveSitting: ISitting = new SittingClass();

  public activeSitting = new BehaviorSubject<ISitting>(this._tempActiveSitting);

  constructor(private $http: HttpClient) {
    // @ts-ignore
    this.getActiveSitting()
      // @ts-ignore
      .subscribe(sitting => this.activeSitting.next(sitting.activeSitting));
  }

  confirmCouncilliorPresence(sittings_id) {
   return this.$http.post(Config.URI_SaveSittingPresence, {sittings_id: sittings_id});
  }

  getSitting(uuid: string): Observable<ISitting> {
    return this.$http.get<ISitting>(`${Config.URI_AllSittings}/${uuid}`);
  }

  setActiveSitting(uuid): Observable<any> {
    return this.$http.put(Config.URI_SetActiveSitting, {uuid})
      .pipe(map( res => {
        // @ts-ignore
        this.getSitting(uuid)
          .subscribe(res => {
            // @ts-ignore
            this.activeSitting.next(res.sitting);
          });
        return res;
      }));
  }

  getActiveSitting() {
      return this.$http.get<ISitting>(Config.URI_ActiveSitting)
      .pipe(map( sitting => {
        // @ts-ignore
        this.activeSitting.next(sitting.activeSitting);
        return sitting;
      }));
  }

  getSittings() {
    return this.$http.get<ISitting[]>(Config.URI_AllSittings);
  }

  getSittingPresenceList(sitting_uuid) {
    return this.$http.get(`${Config.URI_GetSittingPresenceList}/${sitting_uuid}`);
  }

  saveSitting(sitting: ISitting): Observable<number> {
    return this.$http.post<number>(Config.URI_SaveSitting, sitting);
  }

  editSitting(sitting: ISitting): Observable<number> {
    return this.$http.put<number>(Config.URI_SaveSitting, sitting);
  }

  deleteSitting(id) {
    const address = `${Config.URI_DeleteSitting}/${id}`;
    return this.$http.delete(address);
  }

  deletePresence(uuid) {
    return this.$http.delete(`${Config.URI_DeletePresence}/${uuid}`);
  }


}
