import { Injectable } from '@angular/core';
import {HttpClient} from "@angular/common/http";
import {Config} from "../app/config";
import {Term} from "./term";
import {Observable} from "rxjs";


@Injectable({
  providedIn: 'root'
})
export class TermServiceService {

  getTerm(id: number): Observable<Term> {
    return this.$http.get<Term>(`${Config.URI_AllTerms}/${id}`);
  }

  getActiveTerm() {
    return this.$http.get<Term>(Config.URI_ActiveTerm);
  }

  getTerms() {
    return this.$http.get<Term[]>(Config.URI_AllTerms);
  }

  saveTerm(term: Term): Observable<number> {
    return this.$http.post<number>(Config.URI_SaveTerm, term);
  }

  editTerm(term: Term): Observable<number> {
    return this.$http.put<number>(Config.URI_SaveTerm, term);
  }

  deleteTerm(id) {
    const address = `${Config.URI_DeleteTerm}/${id}`;
    return this.$http.delete(address);
  }

  constructor(private $http: HttpClient) {

  }
}
