import {Injectable, OnInit} from '@angular/core';
import {HttpClient} from '@angular/common/http';
import {Config} from './config';
import {ReplaySubject, Subject} from 'rxjs';
import * as io from 'socket.io-client';

@Injectable({
  providedIn: 'root'
})
export class UtilitiesService {

  public socket;

  constructor(private $http: HttpClient) {
    this.connectToSocket();
  }

  public connectToSocket() {
    this.socket = io.connect();
  }

  public disconenctSocket() {
    if (this.socket !== undefined || this.socket !== null) { return; }
    this.socket.close();
   // this.socket = io.connect('');
  }

  public getConstituencies() {
      return this.$http.get(Config.URI_AllConstituencies);
  }

  public getUsers() {
      return this.$http.get(Config.URI_AllUsers);
  }

  public getUsableUsers() {
      return this.$http.get(Config.URI_AllUsableUsers);
  }



}
