import { BrowserModule } from '@angular/platform-browser';
import {NgModule} from '@angular/core';

import {BrowserAnimationsModule} from '@angular/platform-browser/animations';
import {RouterModule, Routes} from '@angular/router';
import {routes} from './routes';
import { ReactiveFormsModule } from '@angular/forms';
import {HTTP_INTERCEPTORS, HttpClientModule} from '@angular/common/http';

import { AppRoutingModule } from './app-routing.module';
import { AppComponent } from './app.component';
import {NavbarComponent} from './navbar/navbar.component';

import { TermFormComponent } from './terms/term-form/term-form.component';
import {TermsComponent} from './terms/terms.component';
import {TermServiceService} from '../app/term-service.service';
import {AlertService} from './alert.service';
import { SittingsComponent } from './sittings/sittings.component';
import { SittingFormComponent } from './sittings/sitting-form/sitting-form.component';
import { VotingsComponent } from './votings/votings.component';
import { VotingFormComponent } from './votings/voting-form/voting-form.component';
import { CouncillorsComponent } from './councillors/councillors.component';
import { CouncillorFormComponent } from './councillors/councillor-form/councillor-form.component';
import { UserComponent } from './users/user.component';
import { UserFormComponent } from './users/user-form/user-form.component';
import { SafePipe } from './safe.pipe';
import { LoginComponent } from './login/login.component';
import { VotingResultComponent } from './voting-result/voting-result.component';
import { HomeComponent } from './home/home.component';
import { SittingPresenceListComponent } from './sitting-presence-list/sitting-presence-list.component';
import {RequestInterceptor} from './request-interceptor.service';
import { ActiveStatusPipe } from './active-status.pipe';
import { ToastrModule  } from 'ngx-toastr';
import { ChartModule } from 'angular2-chartjs';
import { ConfigComponent } from './configs/config.component';


@NgModule({
  declarations: [
    AppComponent,
    NavbarComponent,
    TermFormComponent,
    TermsComponent,
    SittingsComponent,
    SittingFormComponent,
    VotingsComponent,
    VotingFormComponent,
    CouncillorsComponent,
    CouncillorFormComponent,
    UserComponent,
    UserFormComponent,
    SafePipe,
    LoginComponent,
    VotingResultComponent,
    HomeComponent,
    SittingPresenceListComponent,
    ActiveStatusPipe,
    ConfigComponent,
  ],
  imports: [
    BrowserModule,
    AppRoutingModule,
    BrowserAnimationsModule,
    ReactiveFormsModule,
    HttpClientModule,
    ChartModule,
    ToastrModule.forRoot(),
    RouterModule.forRoot(routes, {useHash: true})
  ],
  providers: [
    TermServiceService,
    AlertService,
  {
    provide: HTTP_INTERCEPTORS,
    useClass: RequestInterceptor,
    multi: true
  }
  ],
  bootstrap: [AppComponent]
})
export class AppModule { }
