import {Injectable} from '@angular/core';
import {BehaviorSubject, Subject} from 'rxjs';
import {IAlert} from './ialert';

@Injectable({
  providedIn: 'root'
})
export class AlertService {

  emitAlert = new BehaviorSubject<any>({});

  emitAlertEvent$ = this.emitAlert.asObservable();

  emitAlertNext(alert: IAlert) {
    this.emitAlert.next(alert);
  }

  clearAlert() {
    this.emitAlert.next({});
  }

  constructor() {
  }
}
