import {Component, ElementRef, OnInit, ViewChild} from '@angular/core';
import {ActivatedRoute} from '@angular/router';
import {ConfigService} from './config.service';
import {AlertService} from '../alert.service';
import {AlertType} from '../alert-type.enum';

@Component({
  selector: 'app-config',
  templateUrl: './config.component.html',
  styleUrls: ['./config.component.css']
})
export class ConfigComponent implements OnInit {

  public configs: any[];
  private isInEditMode: boolean;

  constructor(private activatedRoute: ActivatedRoute,
              private configService: ConfigService,
              private alertService: AlertService
  ) {
  }

  ngOnInit(): void {
    this.activatedRoute.data
      .subscribe(data => this.setData(data.data));
  }

  private setData(dataToSet) {
    this.configs = dataToSet;
  }

  private editSettingValue(event: MouseEvent, key) {
    if (this.isInEditMode) {
      this.alertService.emitAlertNext({type: AlertType.warning, title: 'Już edytujesz',
        message: `Już jesteś w trybie edycji!`});
      return; }
    
    this.isInEditMode = true;
    const element: EventTarget = event.target || event.srcElement || event.currentTarget;
    // @ts-ignore
    const oldValue = element.innerText;

    // @ts-ignore
    element.contentEditable = true;

    // @ts-ignore
    const saveIcon = element.nextSibling;
    saveIcon.hidden = false;
    saveIcon.addEventListener('click', (click) => {
      // @ts-ignore
      if (oldValue === element.innerText) {
        this.alertService.emitAlertNext({type: AlertType.warning, title: 'Brak zmiany',
          message: `Ustawienie ${key} nie zostało zmienione przez użytkownika`});
        saveIcon.hidden = true;
        // @ts-ignore
        element.contentEditable = false;
        this.isInEditMode = false;
        this.configService.getAllConfigs()
          .subscribe(res => this.setData(res));
        return;
      }
      // @ts-ignore
      this.saveConfigValue(key, element.innerText)
        .subscribe( res => {
          if (res === 1) {
            this.alertService.emitAlertNext({type: AlertType.info, title: 'Zapisano',
              message: `Ustawienie ${key} zostało zaktualizowane`});
            saveIcon.hidden = true;
            // @ts-ignore
            element.contentEditable = false;
            this.isInEditMode = false;
            this.configService.getAllConfigs()
              .subscribe(res => this.setData(res));
          } else {
            this.alertService.emitAlertNext({type: AlertType.error, title: 'Błąd',
              message: `Ustawienie ${key} nie zostało zaktualizowane`});
            this.isInEditMode = false;
            this.configService.getAllConfigs()
              .subscribe(res => this.setData(res));
          }
        });
    });
  }

  private saveConfigValue(key, newValue) {
    return this.configService.setConfig(key, newValue);
  }

}
