import {Component, OnInit} from '@angular/core';
import {TermServiceService} from '../../term-service.service';
import {FormBuilder, FormGroup, Validators} from '@angular/forms';
import {Term} from '../../term';
import {ISitting} from '../../isitting';
import {SittingService} from '../../sitting.service';
import {ActivatedRoute, Router} from '@angular/router';
import {SittingClass} from '../../sitting-class';
import {Location} from '@angular/common';

@Component({
  selector: 'app-sitting-form',
  templateUrl: './sitting-form.component.html',
  styleUrls: ['./sitting-form.component.css']
})
export class SittingFormComponent implements OnInit {

  termsList: Term[];
  sitting: ISitting;
  sittingForm: FormGroup = this.formBuilder.group({
    date: ['', Validators.required],
    number: ['', Validators.required],
    term_id: ['', Validators.required],
    active: false
  });

  submitSittingForm() {
    this.sitting.date = this.sittingForm.value.date;
    this.sitting.number = this.sittingForm.value.number;
    this.sitting.term_id = this.sittingForm.value.term_id;
    this.sitting.active = this.sittingForm.value.active;

    if (this.sitting.active) {
      // @ts-ignore
      this.sittingService.getActiveSitting()
        .subscribe(sittings => {
          // @ts-ignore
          if (sittings.activeSitting !== undefined) {
            if (!confirm('Zostało zaznaczone pole Czy aktualna?. Zastapić aktualną sesję nową?')) {
              this.sitting.active = false;
            }
          }
          this.saveSittingForm();
        });

    } else {
      this.saveSittingForm();

    }
  }

  constructor(private termService: TermServiceService,
              private formBuilder: FormBuilder,
              private sittingService: SittingService,
              private router: Router,
              private location: Location,
              private activateRoute: ActivatedRoute) {
  }

  ngOnInit() {
    this.termService.getTerms()
    // @ts-ignore
      .subscribe(res => this.termsList = res.terms);
    this.activateRoute.snapshot.params.uuid === undefined ? this.sitting = new SittingClass() : this.setDataFromResolver();
  }

  setDataFromResolver() {
    this.activateRoute.data
      .subscribe(res => {
        // @ts-ignore
        this.sitting = res.data.sitting;
        this.sittingForm = this.formBuilder.group({
          uuid: [this.sitting.uuid],
          date: [this.sitting.date.substring(0, 10), Validators.required],
          number: [this.sitting.number, Validators.required],
          term_id: [this.sitting.term_id, Validators.required],
          active: this.sitting.active,
          created_at: [this.sitting.created_at],
          updated_at: [this.sitting.updated_at],
        });
      });
  }

  resetForm() {
    this.sittingForm.reset();
  }

  private saveSittingForm() {
    if (this.sitting.hasOwnProperty('id')) {
      this.sittingService.editSitting(this.sitting)
        .subscribe((res) => {
            this.router.navigateByUrl('/sittings');
          },
          error1 => console.log(error1.error)
        );
    } else {
      this.sittingService.saveSitting(this.sitting)
        .subscribe((res) => {
            this.router.navigateByUrl('/sittings');
          },
          error1 => console.log(error1)
        );
    }
  }

  goBack() {
    this.location.back();
  }

}
