import { Injectable } from '@angular/core';
import {HttpClient} from "@angular/common/http";
import {Config} from "./config";
import {IUser} from "./iuser";

@Injectable({
  providedIn: 'root'
})
export class UserService {

  saveUser(user: IUser) {
    return this.$http.post(Config.URI_SaveUser, user);
  }

  editUser(user: IUser) {
    return this.$http.put(Config.URI_SaveUser, user);
  }

  getUser(uuid) {
    return this.$http.get(`${Config.URI_AllUsers}/${uuid}`)
  }

  deleteUser(uuid) {
    return this.$http.delete(`${Config.URI_AllUsers}/${uuid}`)
  }

  constructor(private $http: HttpClient) { }
}
