import { Component, OnInit } from '@angular/core';
import {ISitting} from '../isitting';
import {SittingService} from '../sitting.service';
import {Term} from '../term';
import {TermServiceService} from '../term-service.service';
import {TermClass} from '../TermClass';
import {UtilitiesService} from '../utilities.service';
import {UserClass} from '../user-class';
import {LoginService} from '../login.service';
import {AlertType} from '../alert-type.enum';
import {AlertService} from '../alert.service';

@Component({
  selector: 'app-sittings',
  templateUrl: './sittings.component.html',
  styleUrls: ['./sittings.component.css']
})
export class SittingsComponent implements OnInit {

  sittings: ISitting[];
  presence;
  activeTerm: Term = new TermClass();
  user = new UserClass();
  private socket;

  constructor(private sittingService: SittingService,
              private termService: TermServiceService,
              private loginService: LoginService,
              private alertService: AlertService,
              private utilitiesService: UtilitiesService) {

   this.socket = this.utilitiesService.socket;
   this.socket.on('sittings-presence', d => {
     // @ts-ignore
     const sittings_id_where_presence = this.sittings.findIndex(s => s.id == d.sittings_id);
     this.sittings[sittings_id_where_presence].presence_number++;
   });
    this.socket.on('sittings-active', d => {
     // @ts-ignore
   });
  }

  ngOnInit() {
    this.getAllSittings();

    this.loginService.loggedUser
      .subscribe(v => Object.assign(this.user, JSON.parse(localStorage.getItem('user'))));

    this.termService.getActiveTerm()
    // @ts-ignore
      .subscribe(res => this.activeTerm = res.activeTerm);
  }

  isPresence(sitting: ISitting): boolean {
    // @ts-ignore
    if (sitting.iam === 1) { return true; }
    return false;
  }

  setActiveSitting(sitting) {
    const isOld  = new Date(sitting.date) < (new Date());
    if (isOld) {
      this.alertService.emitAlertNext({type: AlertType.info, title: 'Sesja zakończona!',
        message: `Wybrana sesja jest z przeszłości`});
    }
    const uuid = sitting.uuid;
    this.sittingService.setActiveSitting(uuid)
      .subscribe(res => {
        this.getAllSittings();
        this.alertService.emitAlertNext({type: AlertType.success, title: 'Sesja aktywna',
          message: `Sesja została aktywowana.`});
      });
  }

  confirmPresence(sitting) {
    this.sittingService.confirmCouncilliorPresence(sitting.id)
      .subscribe(res => {
        sitting.iam = 1;
        this.alertService.emitAlertNext({type: AlertType.info, title: 'Obecny',
          message: `Witaj na sesji!`});
      }
  );
  }

  deleteSitting(s: ISitting) {
    if (!confirm(`Usunąć sesję numer ${s.number} z dnia ${s.date}`)) { return; }
    this.sittingService.deleteSitting(s.uuid)
      .subscribe(res => {
        this.getAllSittings();
        this.alertService.emitAlertNext({type: AlertType.info, title: 'Usunięto',
          message: `Sesja ${s.number} została usunięta poprawnie.`});
        // @ts-ignore
      });
  }

  getAllSittings() {
    this.sittingService.getSittings()
      .subscribe((res) => {
          // @ts-ignore
          this.sittings = res.sittings;
        },
        error1 => {

        }
      );
  }



}
